if GAIN.shape != (CLASS_COUNT,):
    raise ValueError(f"GAIN must have shape ({CLASS_COUNT},), got {GAIN.shape}")
WEIGHT_MATRIX *= GAIN[:, None, None]

# Online recurrent state for one event stream.
S_STATE = np.zeros(CLASS_COUNT, dtype=np.float32)
LAST_T = None

# Pre-computed vector for vectorized decay (avoid per-element np.exp in loops)
_TAU_CLIP = np.maximum(TAU, EPS)  # shape (13,)


def apply_decay(dt):
    """Apply vectorized time decay to S_STATE.  Call once per batch, before events."""
    global S_STATE
    if dt > 0:
        S_STATE *= np.exp(-dt / _TAU_CLIP)


def accumulate(x, y):
    """Add weight at (x, y) to S_STATE without decay.  Call per event."""
    global S_STATE
    S_STATE += WEIGHT_MATRIX[:, int(y), int(x)]


def set_last_t(t):
    """Manually update LAST_T for batch-level time management."""
    global LAST_T
    LAST_T = float(t) if t is not None else None


def compute_score_info():
    """Return a score-info dict from the current S_STATE (no side effects)."""
    s = S_STATE
    shifted = s - float(np.max(s))
    exp_s = np.exp(shifted)
    prob = exp_s / max(float(np.sum(exp_s)), EPS)
    pred_idx = int(np.argmax(prob))
    return {
        "score": prob.astype(np.float32),
        "S": s.copy(),
        "prob": prob,
        "strength": float(np.max(s)),
        "pred_class": pred_idx + 1,
        "pred_label": CLASS_LABELS[pred_idx],
    }


def init_scorer():
    """Runtime init hook. Constants are already embedded, so just reset state."""
    reset_score()


def reset_score(t=None, initial_state=None):
    """Call this once when a new event stream starts."""
    global LAST_T

    if initial_state is None:
        S_STATE[:] = 0.0
    else:
        state = np.asarray(initial_state, dtype=np.float32)
        if state.shape != (CLASS_COUNT,):
            raise ValueError(f"initial_state must have shape ({CLASS_COUNT},), got {state.shape}")
        S_STATE[:] = state

    LAST_T = None if t is None else float(t)


def softmax_13(values):
    """Numerically stable 13-class softmax."""
    max_value = float(np.max(values))
    exp_values = np.exp(values - max_value)
    return exp_values / max(float(np.sum(exp_values)), EPS)


def sigmoid(value):
    return 1.0 / (1.0 + np.exp(-value))


def _update_state(x, y, t):
    global LAST_T

    x_int = int(x)
    y_int = int(y)
    if x_int < 0 or x_int >= XY_SIZE or y_int < 0 or y_int >= XY_SIZE:
        raise ValueError(f"x and y must be integers in 0..{XY_SIZE - 1}, got x={x}, y={y}")

    t_now = float(t)
    dt = 0.0 if LAST_T is None else max(t_now - LAST_T, 0.0)
    LAST_T = t_now

    apply_decay(dt)
    accumulate(x, y)


def get_score(x, y, t, return_info=False):
    """Update state with one event and return the current 13-class score.

    Input:
        x, y: integer event coordinates, both in 0..127.
        t: event timestamp. Unit must match training data; current CSVs use us.

    Online update:
        S_i(t) = S_i(t_last) * exp(-(t - t_last) / tau_i) + WEIGHT_MATRIX[i,y,x]

    Output score:
        prob_i = softmax(S)_i

    Gate/threshold logic is intentionally not applied here. Add it outside this
    function if needed.
    """
    _update_state(x, y, t)
    score = softmax_13(S_STATE).astype(np.float32)
    strength = float(np.max(S_STATE))

    if not return_info:
        return score

    pred_index = int(np.argmax(score))
    return {
        "score": score,
        "S": S_STATE.copy(),
        "prob": score.copy(),
        "strength": strength,
        "pred_class": pred_index + 1,
        "pred_label": CLASS_LABELS[pred_index],
    }


def get_score_with_gate(x, y, t, return_info=False):
    """Update state with one event and return gate * softmax(S_STATE)."""
    _update_state(x, y, t)
    prob = softmax_13(S_STATE).astype(np.float32)
    strength = float(np.max(S_STATE))
    gate = sigmoid((strength - ACTIVATION_THRESHOLD) / GATE_TEMPERATURE)
    score = (gate * prob).astype(np.float32)

    if not return_info:
        return score

    pred_index = int(np.argmax(score))
    return {
        "score": score,
        "S": S_STATE.copy(),
        "prob": prob.copy(),
        "gate": float(gate),
        "strength": strength,
        "pred_class": pred_index + 1,
        "pred_label": CLASS_LABELS[pred_index],
    }


# Compatibility names for the earlier Python notebook interface.
def reset_Score(t=None, initial_state=None):
    reset_score(t=t, initial_state=initial_state)


def get_Score(x, y, t, return_info=False):
    return get_score(x=x, y=y, t=t, return_info=return_info)


def get_Score_with_gate(x, y, t, return_info=False):
    return get_score_with_gate(x=x, y=y, t=t, return_info=return_info)
